        3 => [
            [
                'text' => 'Define Center of Gravity (G), Center of Buoyancy (B), and Transverse Metacenter (M).',
                'category' => 'technical',
                'duration_seconds' => 120,
                'note' => 'G is the point through which the ship\'s total weight acts vertically downward; B is the geometric centroid of the underwater displaced volume acting vertically upward; M is the intersection of vertical lines through B at upright and very small angles of heel (<10°–15°).',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'Define Metacentric Height (GM) and Righting Lever (GZ).',
                'category' => 'technical',
                'duration_seconds' => 90,
                'note' => 'GM is the vertical distance between G and M (measuring initial stability); GZ is the horizontal perpendicular distance between the downward force through G and the upward buoyancy force through B when heeled (so Righting Moment=Δ×GZ).',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'Compare Stable, Neutral, and Unstable Equilibrium.',
                'category' => 'technical',
                'duration_seconds' => 90,
                'note' => 'Stable: G is below M (GM>0, ship returns upright when heeled); Neutral: G coincides with M (GM=0, rests at small inclination); Unstable: G is above M (GM<0, heels further until reaching Angle of Loll or capsizing).',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'Compare a Stiff Ship and a Tender Ship.',
                'category' => 'technical',
                'duration_seconds' => 90,
                'note' => 'A Stiff ship has a very large GM (short, violent rolling period—typical of a loaded iron ore carrier); a Tender ship has a very small positive GM (long, slow, easy roll—typical of a timber carrier).',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'What is the difference between List and Loll?',
                'category' => 'technical',
                'duration_seconds' => 120,
                'note' => 'List occurs when G moves off the centerline (GG₁ transverse) while GM remains positive; Angle of Loll occurs when G remains on the centerline but rises above M (GM is negative), causing the ship to flop to either side until B moves out far enough vertically below G.',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'What is the value of GZ at the Angle of Loll?',
                'category' => 'technical',
                'duration_seconds' => 90,
                'note' => 'Zero (GZ=0); the vessel is in temporary stable equilibrium at that heeled angle, though with severely reduced residual range of stability.',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'How do you distinguish between List and Loll at sea if unsure?',
                'category' => 'technical',
                'duration_seconds' => 90,
                'note' => 'Check tank soundings and cargo distribution first; a listing ship rolls equally around a fixed angle on one side, whereas a lolling ship hesitates upright and flops lazily from port Loll to starboard Loll in waves.',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'How do you safely correct an Angle of Loll?',
                'category' => 'technical',
                'duration_seconds' => 120,
                'note' => 'Eliminate upper free surfaces, secure weights, and add ballast to a divided double-bottom tank starting on the LOW side first (so the initial increase in list is controlled rather than causing the ship to slam violently across to the other side), then fill the high-side tank.',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'Why must you NEVER start correcting an Angle of Loll by filling a double-bottom tank on the HIGH side?',
                'category' => 'technical',
                'duration_seconds' => 90,
                'note' => 'Because adding free surface before the added weight lowers G below M will temporarily worsen the negative GM, and once the high-side weight takes effect, the ship will roll violently past upright to an even greater angle on the opposite side.',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'What are the mandatory IMO Intact Stability Criteria for general cargo ships?',
                'category' => 'technical',
                'duration_seconds' => 120,
                'note' => '1) Area under GZ curve up to 30° ≥0.055 m-rad; 2) Area up to 40° (or flooding angle θf) ≥0.090 m-rad; 3) Area between 30° and 40° (or θf) ≥0.030 m-rad; 4) GZ≥0.20 m at an angle ≥30°; 5) Maximum GZ occurs at an angle preferably >30°, but never <25°; 6) Initial GM₀ ≥0.15 m.',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'What is Free Surface Effect (FSE) and how do you minimize it at the design or operational stage?',
                'category' => 'technical',
                'duration_seconds' => 120,
                'note' => 'When a partially filled tank heels, the liquid wedge shifts toward the low side, shifting the tank\'s center of gravity and causing a virtual rise in the ship\'s KG (FSC = i × ρ tank / Δ); dividing a tank longitudinally into n equal compartments reduces FSE to 1/n² of its original value.',
                'topic' => 'Transverse Stability, GM & Loll Management',
                'needs_review' => false,
            ],
            [
                'text' => 'Does the quantity of liquid inside a slack rectangular tank change its Free Surface Moment?',
                'category' => 'technical',
                'duration_seconds' => 90,
                'note' => 'No (as long as the liquid neither hits the tank top nor uncovers the tank bottom during heel); FSM depends solely on the second moment of area of the liquid surface (L×B³/12) and liquid density.',
