                'needs_review' => false,
            ],
            [
                'text' => 'What is the Wall-Sided Formula and when is it used?',
                'category' => 'technical',
                'duration_seconds' => 90,
                'note' => 'GZ = sinθ (GM + ½ BM tan²θ); used to calculate GZ at moderate angles of heel (beyond 10°–15° up to deck edge immersion) and to derive the Angle of Loll formula (tanθ(loll) = √(−2GM / BM)).',
                'topic' => 'Transverse Stability, GM & Loll Management',
